      '/// A byte size paired with a non-zero power-of-two alignment.\npub struct Layout {\n  pub bytes: usize\n  pub alignment: usize\n}\n\npub struct InvalidAlignment {\n  pub alignment: usize\n}\n\npub struct LayoutOverflow {}\n\n/// Returns the compiler-selected layout of T.\npub fn of<T>() -> Layout {\n  return Intrinsic.layoutOf<T>()\n}\n\n/// Constructs a layout from an explicit size and alignment.\npub fn make(size: usize, alignment: usize) -> Layout | InvalidAlignment {\n  if alignment == 0 {\n    return InvalidAlignment { alignment: alignment }\n  }\n  let previous = alignment - 1\n  if usize.bitAnd(alignment, previous) != 0 {\n    return InvalidAlignment { alignment: alignment }\n  }\n  return Layout { bytes: size, alignment: alignment }\n}\n\n/// Repeats a layout with checked aggregate-size semantics.\npub fn repeat(layout: Layout, count: usize) -> Layout | LayoutOverflow {\n  return match move usize.checkedMultiply(layout.bytes, count) {\n    None {} => LayoutOverflow {}\n    Some<usize> { value } => Layout { bytes: value, alignment: layout.alignment }\n  }\n}\n',
