    source:
      "// Allocation counts an allocator provider can publish as an ordinary Silk value. No compiler\n// phase knows this module: every count is a plain `usize`, so `AllocationMetrics` is a Copy\n// struct that implements no Drop hook and carries no cleanup obligation, and a provider folds\n// its own events into one with ordinary field assignment.\n//\n// A program that never names this module never loads it, so the counts cost nothing until they\n// are read.\n\n/// The acquire, release, and peak-live counts one allocation provider has observed.\npub struct AllocationMetrics {\n  pub acquired: usize\n  pub released: usize\n  pub peakLive: usize\n}\n\n/// Constructs the zeroed counts a provider starts from.\npub fn make() -> AllocationMetrics {\n  return AllocationMetrics { acquired: usize.ZERO, released: usize.ZERO, peakLive: usize.ZERO }\n}\n\n/// Reads one independent snapshot through a shared borrow. Every field is Copy, so publishing\n/// the counts never moves the provider's own value out of it.\npub fn copy(self: &AllocationMetrics) -> AllocationMetrics {\n  return AllocationMetrics {\n    acquired: self.acquired,\n    released: self.released,\n    peakLive: self.peakLive\n  }\n}\n\n/// The allocations acquired and not yet released.\npub fn live(self: &AllocationMetrics) -> usize {\n  return self.acquired - self.released\n}\n\n/// Records one acquired allocation, raising the peak when the new live count exceeds it.\npub fn recordAcquire(self: &mut AllocationMetrics) -> () {\n  self.acquired = self.acquired + usize.ONE\n  let current = self.acquired - self.released\n  if current > self.peakLive {\n    self.peakLive = current\n  }\n  return ()\n}\n\n/// Records one released allocation. The peak keeps the highest live count ever observed.\npub fn recordRelease(self: &mut AllocationMetrics) -> () {\n  self.released = self.released + usize.ONE\n  return ()\n}\n",
