    source:
      '// Canonical completed typed outcome data. Failure rows project to ordinary value sums through\n// Row<! E>; Result itself remains ordinary source-defined data with no runtime row descriptor.\n\n/// The successful member of a completed outcome.\npub struct Success<A> {\n  /// The produced success value.\n  value: A\n}\n\n/// The failed member of a completed outcome.\npub struct Failure<F> {\n  /// The produced failure value.\n  error: F\n}\n\n/// One completed outcome: either a success carrying `A` or a failure carrying `F`.\n///\n/// `Result` is the reified form of an Effect that has already run. Reifying an Effect turns its\n/// failure row into ordinary value data, which is what lets the failure combinators in\n/// `silk.effects` be written as ordinary Silk source instead of compiler built-ins.\npub struct Result<A, F> {\n  /// The completed outcome, narrowed with `match`.\n  value: Success<A> | Failure<F>\n}\n\n/// Constructs a completed successful outcome.\npub fn succeed<A, F>(value: A) -> Result<A, F> {\n  return Result<A, F> { value: Success<A> { value: move value } }\n}\n\n/// Constructs a completed failed outcome.\npub fn failResult<A, F>(error: F) -> Result<A, F> {\n  return Result<A, F> { value: Failure<F> { error: move error } }\n}\n',
